def write_pages():
    (OUT/'assets/flow-data.js').write_text('window.PROBATUM_FLOWS = '+json.dumps(reviewed_data(public_data()),ensure_ascii=False,separators=(',',':'))+';\n')
    flow_assets = ''.join(f'<link rel="stylesheet" href="/assets/{name}?v={hashlib.sha256((OUT/"assets"/name).read_bytes()).hexdigest()[:10]}">' if name.endswith('.css') else f'<script src="/assets/{name}?v={hashlib.sha256((OUT/"assets"/name).read_bytes()).hexdigest()[:10]}" defer></script>' for name in ['flow.css','flow-data.js','flow.js'])
    cinematic_assets = ''.join(f'<link rel="stylesheet" href="/assets/{name}?v={hashlib.sha256((OUT/"assets"/name).read_bytes()).hexdigest()[:10]}">' if name.endswith('.css') else f'<script src="/assets/{name}?v={hashlib.sha256((OUT/"assets"/name).read_bytes()).hexdigest()[:10]}" defer></script>' for name in ['cinematic.css','cinematic.js'])
    studio_assets = ''.join(f'<link rel="stylesheet" href="/assets/{name}?v={hashlib.sha256((OUT/"assets"/name).read_bytes()).hexdigest()[:10]}">' if name.endswith('.css') else f'<script src="/assets/{name}?v={hashlib.sha256((OUT/"assets"/name).read_bytes()).hexdigest()[:10]}" defer></script>' for name in ['studio.css','studio.js','openings.css','openings.js'])
    journey_css=hashlib.sha256((OUT/'assets/journey.css').read_bytes()).hexdigest()[:10]
    journey_js=hashlib.sha256((OUT/'assets/journey.js').read_bytes()).hexdigest()[:10]
    css=hashlib.sha256((OUT/'assets/site.css').read_bytes()).hexdigest()[:10]
    js=hashlib.sha256((OUT/'assets/site.js').read_bytes()).hexdigest()[:10]
    nav=[('oferta.html','Oferta'),('realizacje.html','Projekty'),('o-donie.html','Podejście'),('automatyzacja.html','Agenci AI'),('blog.html','Wiedza')]
    for path,(title,desc,body,cls) in PAGES.items():
        title = title.replace(' — ', ' | ')
        canon = BASE + ('/' if path == 'index.html' else '/' + path)
        links=''.join(f'<a href="/{url}" {"aria-current=page" if path==url else ""}>{label}</a>' for url,label in nav)
        footerlinks=''.join(f'<a href="/{url}">{label}</a>' for url,label in [('strony-www.html','Strony internetowe'),('marketing.html','Marketing i kampanie'),('social-media.html','Social media'),('automatyzacja.html','Automatyzacje i AI'),('akademia.html','Akademia AI')])
        morelinks=''.join(f'<a href="/{url}">{label}</a>' for url,label in [('realizacje.html','Projekty'),('o-donie.html','Nasze podejście'),('blog.html','Baza wiedzy'),('warsztat.html','Warsztat'),('wycena.html','Zapytaj o wycenę')])
        page=f'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="robots" content="{'noindex,nofollow' if PRYWATNY else 'index,follow'}"><link rel="canonical" href="{canon}"><meta property="og:type" content="website"><meta property="og:site_name" content="Probatum"><meta property="og:locale" content="pl_PL"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(desc, quote=True)}"><meta property="og:url" content="{canon}"><meta property="og:image" content="{BASE}/assets/og-probatum.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="675"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#fbfcf8"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css?v={css}"><script src="/assets/site.js?v={js}" defer></script>{flow_assets if "data-flow-scene" in body else ""}{cinematic_assets if any(marker in body for marker in ["data-restoration", "data-spring-opening", "data-live-projects"]) else ""}{f'<link rel="stylesheet" href="/assets/journey.css?v={journey_css}">' if cls in ['home','approach','offer'] else ''}{f'<script src="/assets/journey.js?v={journey_js}" defer></script>' if 'data-foundation' in body else ''}{studio_assets}</head><body class="{cls}"><div class="studio-reading-line" aria-hidden="true" data-studio-progress></div><a class="skip-link" href="#main">Przejdź do treści</a><header class="site-header"><div class="header-inner"><a class="wordmark" href="/index.html" aria-label="Probatum — strona główna">probatum<span class="logo-dot">.</span></a><nav class="desktop-nav" aria-label="Główna nawigacja">{links}</nav><a class="header-cta" href="/kontakt.html">Kontakt</a><button class="menu-button" type="button" aria-expanded="false" aria-controls="mobile-menu" aria-label="Otwórz menu"><span></span><span></span></button></div><nav id="mobile-menu" class="mobile-menu" aria-label="Menu mobilne" hidden>{links}<a href="/akademia.html">Akademia AI</a><a href="/kontakt.html">Kontakt</a></nav></header><main id="main">{body}</main><footer class="footer"><div class="container"><div class="footer-top"><div><a class="wordmark" href="/index.html">probatum<span class="logo-dot">.</span></a><p>Dobry design.<br>Jasny przekaz.<br>Wspólny kierunek.</p></div><nav aria-label="Usługi w stopce"><p class="eyebrow">CO ROBIMY</p>{footerlinks}</nav><nav aria-label="Informacje w stopce"><p class="eyebrow">POZNAJ NAS</p>{morelinks}</nav><div class="footer-contact"><p class="eyebrow">ZACZNIJMY OD ROZMOWY</p><a href="mailto:{EMAIL}">{EMAIL}</a><a href="tel:+48573569141">{PHONE}</a><p>Rzeszów / Współpraca w całej Polsce</p></div></div><div class="footer-bottom"><span>© 2026 Probatum</span><a href="/cookies.html">Cookies i dane</a><a href="#main">Do góry ↑</a></div><div class="footer-word" aria-hidden="true">probatum.</div></div></footer><div class="mobile-contact"><a href="tel:+48573569141">Zadzwoń <span aria-hidden="true">↗</span></a><a href="/kontakt.html">Omów projekt <span aria-hidden="true">↗</span></a></div></body></html>'''
        dest=OUT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(reviewed_copy(calm_markup(page)))
    if PRYWATNY:
        (OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
    else:
        # Strony klientow w p/ maja wlasne mapy strony i nic do nich nie linkuje
        # z poziomu probatum.pl — bez tego wpisu robot nie ma jak ich znalezc.
        mapy = [BASE + '/sitemap.xml',
                BASE + '/p/newage-lewandowska/sitemap.xml']
        (OUT/'robots.txt').write_text('User-agent: *\nAllow: /\n\n'
                                      + ''.join('Sitemap: %s\n' % m for m in mapy))
        from datetime import date
        dzis = date.today().isoformat()
        # cookies.html to strona techniczna — zostaje poza sitemapa
        adresy = [sc for sc in PAGES if sc != 'cookies.html']
        wpisy = ''.join(
            '<url><loc>%s</loc><lastmod>%s</lastmod><priority>%s</priority></url>'
            % (BASE + ('/' if sc == 'index.html' else '/' + sc), dzis,
               '1.0' if sc == 'index.html' else '0.6' if '/' in sc else '0.8')
            for sc in adresy)
        (OUT/'sitemap.xml').write_text(
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + wpisy + '</urlset>\n')

    # Spis stron wytworzonych przez ten generator. Lezy przy generatorze,
    # nie na publicznym poziomie — publikuj.py kasuje po nim osierocone pliki.
    (ROOT/'MANIFEST-v2.txt').write_text('\n'.join(sorted(PAGES))+'\n')
    print(f'Wrote {len(PAGES)} complete pages.')

if __name__=='__main__':
    # Page definitions are inserted above this call as the site is authored.
    write_pages()
